export function getCategoryFallbackImageUrl(category?: string | null): string {
  switch (category) {
    case "bakliyat":
      return "/products/pirinc.jpg";
    case "temizlik":
      return "/products/camasir-suyu.jpg";
    case "kisisel":
      return "/products/sampuan.jpg";
    case "gida":
    default:
      return "/products/aycicek-yagi.jpg";
  }
}

export function getPublicProductImageUrl(
  url: string | null | undefined,
  productName?: string | null,
  category?: string | null,
): string {
  // 1. Check if direct valid url provided
  if (url && typeof url === "string") {
    const trimmed = url.trim();
    if (trimmed) {
      // Base64 data URLs work anywhere
      if (trimmed.startsWith("data:")) return trimmed;

      // Direct public path
      if (trimmed.startsWith("/products/")) return trimmed;

      // Check direct mapping
      if (PRODUCT_IMAGE_MAP[trimmed]) {
        return PRODUCT_IMAGE_MAP[trimmed];
      }

      // If URL contains /__l5e/assets-v1/...
      if (trimmed.includes("/__l5e/assets-v1/")) {
        const filename = trimmed.split("/").pop();
        if (filename && PRODUCT_IMAGE_MAP[filename]) {
          return PRODUCT_IMAGE_MAP[filename];
        }
        if (filename) {
          return "/products/" + filename;
        }
        return trimmed;
      }

      // If local /src/assets/images/...
      if (trimmed.includes("/src/assets/images/")) {
        const filename = trimmed.split("/").pop();
        return filename ? "/products/" + filename : trimmed;
      }

      // If just a filename without leading slash
      if (PRODUCT_IMAGE_MAP[trimmed]) {
        return PRODUCT_IMAGE_MAP[trimmed];
      }

      if (trimmed.startsWith("http://") || trimmed.startsWith("https://")) {
        return trimmed;
      }
    }
  }

  // 2. Fallback to matching product name against catalog images
  if (productName && typeof productName === "string") {
    const lower = productName.toLocaleLowerCase("tr");
    for (const item of PRODUCT_KEYWORD_MAP) {
      if (item.keywords.some((kw) => lower.includes(kw))) {
        return item.path;
      }
    }
  }

  // 3. Fallback to category default image
  return getCategoryFallbackImageUrl(category);
}

/**
 * Image error handler for standard <img /> tags:
 * Gracefully swaps to category fallback on broken image link without infinite loops.
 */
export function handleProductImageError(
  e: React.SyntheticEvent<HTMLImageElement>,
  productName?: string | null,
  category?: string | null,
) {
  const target = e.currentTarget;
  const fallback = getCategoryFallbackImageUrl(category);
  if (target.src !== fallback && !target.src.endsWith(fallback)) {
    target.src = fallback;
  }
}
